import { HTTPError } from "./error.ts";
import { kHandled } from "./response.ts";

import type { NodeServerRequest, NodeServerResponse, ServerRequest } from "srvx";
import type { H3 } from "./h3.ts";
import type { H3Event } from "./event.ts";
import type { H3EventContext } from "./types/context.ts";
import type { EventHandler, EventHandlerResponse } from "./types/handler.ts";

export type NodeHandler = (
  req: NodeServerRequest,
  res: NodeServerResponse,
) => unknown | Promise<unknown>;

export type NodeMiddleware = (
  req: NodeServerRequest,
  res: NodeServerResponse,
  next: (error?: Error) => void,
) => unknown | Promise<unknown>;

/**
 * @deprecated Since h3 v2 you can directly use `app.fetch(request, init?, context?)`
 */
export function toWebHandler(
  app: H3,
): (request: ServerRequest, context?: H3EventContext) => Promise<Response> {
  return (request, context) => {
    return Promise.resolve(app.request(request, undefined, context || request.context));
  };
}

export function fromWebHandler(
  handler: (request: ServerRequest, context?: H3EventContext) => Promise<Response>,
): EventHandler {
  return function _webHandler(event) {
    return handler(event.req, event.context);
  };
}

/**
 * Convert a Node.js handler function (req, res, next?) to an EventHandler.
 *
 * **Note:** The returned event handler requires to be executed with h3 Node.js handler.
 */
export function fromNodeHandler(handler: NodeMiddleware): EventHandler;
export function fromNodeHandler(handler: NodeHandler): EventHandler;
export function fromNodeHandler(handler: NodeHandler | NodeMiddleware): EventHandler {
  if (typeof handler !== "function") {
    throw new TypeError(`Invalid handler. It should be a function: ${handler}`);
  }
  return function _nodeHandler(event) {
    const node = event.runtime?.node;
    if (!node?.res) {
      throw new Error("[h3] Executing Node.js middleware is not supported in this server!");
    }
    // Legacy handlers route on the raw req.url — sync it with the h3 view so
    // rewrites (withBase/mount) and pathname normalization propagate (#1432)
    const url = event.url.pathname + event.url.search;
    if (node.req.url === url) {
      return callNodeHandler(handler, node.req, node.res, event) as EventHandlerResponse;
    }
    const originalUrl = node.req.url;
    node.req.url = url;
    return (callNodeHandler(handler, node.req, node.res, event) as Promise<unknown>).finally(() => {
      node.req.url = originalUrl;
    }) as EventHandlerResponse;
  };
}

export function defineNodeHandler(handler: NodeHandler): NodeHandler {
  return handler;
}

export function defineNodeMiddleware(handler: NodeMiddleware): NodeMiddleware {
  return handler;
}

function callNodeHandler(
  handler: NodeHandler | NodeMiddleware,
  req: NodeServerRequest,
  res: NodeServerResponse,
  event: H3Event,
) {
  const isMiddleware = handler.length > 2;
  return new Promise((resolve, reject) => {
    res.once("close", () => resolve(kHandled));
    res.once("finish", () => resolve(kHandled));
    res.once("error", (error) => reject(error));
    res.once("pipe", (stream) => {
      resolve(
        new Promise((resolve, reject) => {
          // The response can end before the source does (client disconnect). `pipe` only
          // unpipes (pauses) the source in that case, so it emits neither "close" nor
          // "error" and this promise would stay pending forever — leaving the event
          // lifecycle (`onResponse`, `onDispose`) unfinished and the source alive with
          // its resources (file descriptors, sockets) held. Destroy it to settle both.
          const onResClose = () => {
            stream.destroy();
            resolve(kHandled);
          };
          const settle = (cb: () => void) => {
            res.removeListener("close", onResClose);
            cb();
          };
          const onStreamClose = () => settle(() => resolve(kHandled));
          stream.once("close", onStreamClose);
          stream.once("error", (error: any) =>
            settle(() => {
              // The source emits "close" right after "error": settle once the error hook is done
              stream.removeListener("close", onStreamClose);
              console.error("[h3] Stream error in Node.js handler", {
                cause: error,
              });
              // We cannot alter the outgoing response at this point, so the error hook
              // is only called to report the error (its return value is ignored)
              const config = event.app?.config;
              const onError = config?.onError;
              if (!onError) {
                return reject(kHandled);
              }
              Promise.resolve()
                .then(() => onError(new HTTPError({ cause: error, unhandled: true }), event))
                .catch((hookError) => {
                  if (!config.silent) console.error(hookError);
                })
                .finally(() => reject(kHandled));
            }),
          );
          // The client may have disconnected already — "close" was emitted before this
          // listener could be attached and would never fire.
          if (res.closed || res.destroyed) {
            onResClose();
          } else {
            res.once("close", onResClose);
          }
        }),
      );
    });
    try {
      if (isMiddleware) {
        Promise.resolve(
          handler(req, res, (error) =>
            error ? reject(new HTTPError({ cause: error, unhandled: true })) : resolve(void 0),
          ),
        ).catch((error) => reject(new HTTPError({ cause: error, unhandled: true })));
      } else {
        return Promise.resolve((handler as NodeHandler)(req, res))
          .then(() => resolve(kHandled))
          .catch((error) => reject(new HTTPError({ cause: error, unhandled: true })));
      }
    } catch (error: unknown) {
      reject(new HTTPError({ cause: error, unhandled: true }));
    }
  });
}

